from typing import Iterator
def accumulate(xs: list[int | float]) -> int | float:
    total: int | float = 0
    for x in xs:
        total = total + x
    return total
def snapshots(xs: list[int | float]) -> list[int | float]:
    total: int | float = 0
    saved: list[int | float] = []
    for x in xs:
        saved.append(total)
        saved.append(total)
        total = total + x
    saved.append(total)
    return saved
def handled(xs: list[int | float]) -> int | float:
    total: int | float = 0
    for x in xs:
        try:
            if x == 0:
                raise ValueError("zero")
            total = total + x
        except ValueError:
            total = total * 2
    return total
def yielded(xs: list[int | float]) -> Iterator[int | float]:
    total: int | float = 0
    for x in xs:
        total = total + x
        yield total
